s = 'aab'
rules = {'S': [('A','B')], 'A': [('A','A')]}
term = {'A':'a', 'B':'b'}
n = len(s)
V = [[set() for _ in range(n)] for _ in range(n)]
for i, ch in enumerate(s):
    for A, t in term.items():
        if t == ch:
            V[i][i].add(A)
for L in range(2, n+1):
    for i in range(0, n-L+1):
        j = i + L - 1
        for k in range(i, j):
            for A, ps in rules.items():
                for B, C in ps:
                    if B in V[i][k] and C in V[k+1][j]:
                        V[i][j].add(A)
print(n)
print(n*(n+1)//2)
print(1 if 'S' in V[0][n-1] else 0)
